import {uid} from './core.js';
export const ownerOf=o=>o.panelOf||o.source||o.ownerId||null;
export function layerStack(p,view){const os=p.views[view],gs=p.groups[view],records=[...os,...gs],byId=new Map(records.map(o=>[o.id,o])),known=new Set(byId.keys()),previous=p.layerOrder?.[view]||[],old=new Set(previous),added=os.slice().reverse().map(o=>o.id).filter(id=>!old.has(id)),next=[...new Set([...added,...previous.filter(id=>known.has(id))])],present=new Set(next);for(const g of gs.filter(g=>!present.has(g.id))){const index=next.findIndex(id=>{const r=byId.get(id);return r?.group===g.id||r?.parent===g.id;});next.splice(index<0?0:index,0,g.id);}return next;}
export function ensureLayerOrder(p,view){p.layerOrder??={};p.layerOrder[view]=layerStack(p,view);return p.layerOrder[view];}
export function layerTree(p,view){const os=p.views[view],gs=p.groups[view],order=layerStack(p,view),rank=new Map(order.map((id,i)=>[id,i])),known=new Set([...os,...gs].map(o=>o.id)),all=[...os.map(o=>({id:o.id,kind:'object',value:o,parent:ownerOf(o)||o.group})),...gs.map(g=>({id:g.id,kind:'group',value:g,parent:g.parent}))],children=new Map();for(const r of all){if(!known.has(r.parent))r.parent=null;const key=r.parent||null;if(!children.has(key))children.set(key,[]);children.get(key).push(r);}const walk=(parent,seen=new Set())=>(children.get(parent||null)||[]).filter(r=>!seen.has(r.id)).sort((a,b)=>rank.get(a.id)-rank.get(b.id)).map(r=>({...r,children:[...walk(r.id,new Set([...seen,r.id])),...(r.value.modifiers||[]).map(m=>({id:m.id,kind:'modifier',parent:r.id,value:m,children:[]})),...(r.value.fabricTexture?[{id:r.id+':fabric',kind:'fabric',parent:r.id,value:r.value.fabricTexture,children:[]}]:[])]}));return walk(null);}
export function flattenLayers(tree){return tree.flatMap(r=>[r,...flattenLayers(r.children)]);}
export function layerAncestors(p,view,id){const rows=flattenLayers(layerTree(p,view)),out=[],seen=new Set();let r=rows.find(r=>r.id===id);while(r?.parent&&!seen.has(r.parent)){seen.add(r.parent);out.push(r.parent);r=rows.find(x=>x.id===r.parent);}return out;}
export function createFolder(p,view,parent=null){const g={id:uid(),name:'Carpeta '+String(p.groups[view].length+1).padStart(2,'0'),folder:true};if(parent)g.parent=parent;p.groups[view].push(g);p.layerOrder??={};p.layerOrder[view]=[g.id,...layerStack(p,view).filter(id=>id!==g.id)];return g;}
export function validLayerDrop(p,view,ids,target,position){const rows=flattenLayers(layerTree(p,view)),dest=rows.find(r=>r.id===target);if(!dest||!['object','group'].includes(dest.kind)||position==='inside'&&dest.kind!=='group')return false;const parent=position==='inside'?target:dest.parent;if(parent&&!p.groups[view].some(g=>g.id===parent))return false;ids=ids.filter(id=>!layerAncestors(p,view,id).some(a=>ids.includes(a)));return ids.every(id=>{const r=rows.find(r=>r.id===id);return r&&['object','group'].includes(r.kind)&&!ownerOf(r.value)&&id!==target&&id!==parent&&!layerAncestors(p,view,target).includes(id)&&(!parent||!layerAncestors(p,view,parent).includes(id));});}
export function moveLayers(p,view,ids,target,position){if(!validLayerDrop(p,view,ids,target,position))return false;const rows=flattenLayers(layerTree(p,view)),dest=rows.find(r=>r.id===target),parent=position==='inside'?target:dest.parent,roots=ids.filter(id=>!layerAncestors(p,view,id).some(a=>ids.includes(a))),order=layerStack(p,view),moving=order.filter(id=>roots.includes(id));for(const id of roots){const r=rows.find(r=>r.id===id);const key=r.kind==='group'?'parent':'group';if(parent)r.value[key]=parent;else delete r.value[key];}const next=order.filter(id=>!roots.includes(id));let i=next.indexOf(target);if(position==='below')i++;if(position==='inside')i=next.indexOf(target)+1;next.splice(Math.max(0,i),0,...moving);p.layerOrder[view]=next;p.views[view]=orderedObjects(p,view);return true;}
export function orderedObjects(p,view){const os=p.views[view];if(!p.layerOrder?.[view])return os;const walk=tree=>tree.slice().reverse().flatMap(r=>[...(r.kind==='object'?[r.value]:[]),...walk(r.children)]);return walk(layerTree(p,view));}
export function layerLabel(r){if(r.kind==='fabric')return 'Textura '+({jersey:'Jersey',fleece:'Frisado',waffle:'Waffle',terry:'Rústico',rib:'Rib',denim:'Denim',twill:'Gabardina'}[r.value.type]||r.value.type);if(r.kind==='modifier')return ({stitch:'Costura',fabricFall:'Stack',rib:'Construcción Rib'}[r.value.type]||r.value.type)+(r.value.rows===2?' doble':'');return r.value.name;}

// Presentation only: renderer continues to consume the complete physical tree.
export function logicalLayerId(p,view,id){const os=p.views[view],gs=p.groups[view];const o=os.find(o=>o.id===id)||gs.find(g=>g.id===id);return o?.instanceOf&&(os.some(x=>x.id===o.instanceOf)||gs.some(x=>x.id===o.instanceOf))?o.instanceOf:id;}
export function logicalLayerTree(p,view){const ids=new Set([...p.views[view],...p.groups[view]].filter(o=>o.instanceOf).map(o=>logicalLayerId(p,view,o.id)));const walk=tree=>tree.filter(r=>!r.value.surfaceBoundaryIds&&logicalLayerId(p,view,r.id)===r.id).map(r=>({...r,mirrored:ids.has(r.id),children:walk(r.children)}));return walk(layerTree(p,view));}
